<?php
declare(strict_types=1);
require __DIR__.'/../app/Reports.php';
require __DIR__.'/../app/ReportOutput.php';
date_default_timezone_set('America/Asuncion');
$db=new PDO('sqlite::memory:',null,null,[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]);
$db->exec(str_replace('INTEGER PRIMARY KEY AUTO_INCREMENT','INTEGER PRIMARY KEY AUTOINCREMENT',file_get_contents(__DIR__.'/../database/schema.sql')));
function test(bool $condition,string $message):void{if(!$condition)throw new RuntimeException($message);echo "OK $message\n";}
function denied(callable $f,string $message):void{try{$f();}catch(DomainException $e){echo "OK $message\n";return;}throw new RuntimeException($message);}
$db->exec("INSERT INTO users(id,name,username,password,role) VALUES(1,'Operador','admin','secreto','admin')");
$db->exec("INSERT INTO products(id,code,name,box_size,price,average_cost,min_stock,tax) VALUES(1,'AR','Nombre actual',12,99999,1000,5,5)");
$db->exec("INSERT INTO parties(id,kind,name) VALUES(1,'suppliers','Proveedor')");
$db->exec("INSERT INTO parties(id,kind,name,document) VALUES(2,'customers','Cliente actual','123-0')");
$lot=$db->prepare('INSERT INTO lots(id,product_id,supplier_id,code,expiry,quantity,unit_cost,purchase_tax,reference,received_at,user_id) VALUES(?,1,1,?,?,?,1000,10,?,?,1)');
foreach([[1,'L1','2026-11-20',10,'R1','2026-11-14T03:00:00+00:00'],[2,'VENCIDO','2026-11-13',3,'R2','2026-11-13T20:00:00+00:00'],[3,'L30','2026-12-14',2,'R3','2026-11-13T20:00:00+00:00'],[4,'L60','2027-01-13',1,'R4','2026-11-13T20:00:00+00:00']] as $record)$lot->execute($record);
$movement=$db->prepare("INSERT INTO movements(product_id,lot_id,quantity,type,reference,created_at,user_id) VALUES(1,?,?,?,?,?,1)");
$movement->execute([1,10,'receipt','R1','2026-11-14T03:00:00+00:00']);
$movement->execute([2,3,'receipt','R2','2026-11-13T20:00:00+00:00']);
$snapshot=['customer'=>['id'=>2,'name'=>'Cliente original'],'lines'=>[['product_id'=>1,'code'=>'AR','name'=>'Producto original','quantity'=>2,'unit_price'=>'11000','tax'=>10,'amount'=>'22000','exempt'=>'','vat5_gross'=>'','vat10_gross'=>'22000']],'exempt'=>'0','vat5_gross'=>'0','vat10_gross'=>'22000','iva5'=>'0','iva10'=>'2000','total'=>'22000'];
$db->prepare("INSERT INTO sales(id,operation_key,payload_hash,customer_id,user_id,number,fiscal_key,issued_on,condition_name,credit_days,due_on,total,balance,snapshot,created_at) VALUES(1,'test','hash',2,1,'001-001-0000001','test/1','2026-11-14','credit',30,'2026-11-13',22000,22000,?,'2026-11-14T03:00:00+00:00')")->execute([json_encode($snapshot)]);
$db->exec('INSERT INTO sale_allocations(sale_id,product_id,lot_id,quantity,unit_cost) VALUES(1,1,1,2,1000)');
$r=new Reports($db,['id'=>1,'role'=>'admin'],'2026-11-14');
$stock=$r->run('inventory',[]);
test((int)$stock['rows'][0]['physical']===16 && (int)$stock['rows'][0]['reserved']===2 && (int)$stock['rows'][0]['available']===11,'físico, reservado y apto disponible diferenciados');
$exp=$r->run('expiries',[]);$bands=array_column($exp['rows'],'band','lot');
test($bands['VENCIDO']==='Vencido' && $bands['L1']==='0–7 días' && $bands['L30']==='8–30 días' && $bands['L60']==='31–60 días','rangos de vencimiento excluyentes');
$sale=$r->run('sales',['from'=>'2026-11-14','to'=>'2026-11-14']);
test($sale['rows'][0]['customer']==='Cliente original' && $sale['rows'][0]['total']==='22000','ventas conservan cliente y precio originales');
$vat=$r->run('vat',['from'=>'2026-11-14','to'=>'2026-11-14']);
test($vat['rows'][0]['iva10']==='2000' && $vat['rows'][0]['vat10_gross']==='22000','IVA usa factura y no tasa actual del producto');
test(count($r->run('sales',['from'=>'2026-11-01','to'=>'2026-11-13'])['rows'])===0,'filtro de emisión aplicado');
$mov=$r->run('movements',['from'=>'2026-11-14','to'=>'2026-11-14']);
test(count($mov['rows'])===1 && (int)$mov['rows'][0]['opening']===3 && (int)$mov['rows'][0]['closing']===13,'movimientos respetan medianoche local y saldo por producto');
$balances=$r->run('balances',[]);
test($balances['rows'][0]['band']==='1–30 días' && $balances['rows'][0]['balance']==='22000','antigüedad del saldo actual sin inventar cobros');
test(count($r->run('pending',[])['rows'])===1,'facturas reservadas pendientes de despacho');
test($r->run('margin',['from'=>'2026-11-14','to'=>'2026-11-14'])['rows'][0]['margin']==='18000','margen usa neto original y costo de lotes asignados');
$warehouse=new Reports($db,['id'=>1,'role'=>'deposito'],'2026-11-14');
$safe=$warehouse->run('inventory',[]);
test(!array_key_exists('value',$safe['rows'][0]) && !str_contains(json_encode($safe),'unit_cost'),'depósito no recibe valorizaciones ocultas');
denied(fn()=>$warehouse->run('margin',[]),'margen restringido por servidor');
denied(fn()=>(new Reports($db,['id'=>1,'role'=>'vendedor']))->run('sales',[]),'rol sin cartera implementada no accede a ventas globales');
denied(fn()=>$r->run('sales',['from'=>'2026-02-30','to'=>'2026-11-14']),'fecha inexistente rechazada');
denied(fn()=>$r->run('sales',['from'=>'2026-11-15','to'=>'2026-11-14']),'rango invertido rechazado');
denied(fn()=>$r->run('sales',['product_id'=>1]),'filtro no soportado no se ignora silenciosamente');
test(Reports::csvCell('=HYPERLINK("malicioso")')==="'=HYPERLINK(\"malicioso\")",'CSV neutraliza fórmulas');
test(Reports::csvCell('   +SUM(1,1)')==="'   +SUM(1,1)",'CSV neutraliza fórmulas precedidas por espacios');
test(Reports::csvCell('-100')==='-100','CSV conserva importes numéricos negativos');
test(!str_contains(json_encode($r->options('activity')),'secreto'),'filtros no contienen contraseñas');
$receipt=$r->run('receipts',['from'=>'2026-11-14','to'=>'2026-11-14']);
test((int)$receipt['rows'][0]['quantity']===10,'recepciones muestran ingreso original');
test(!str_contains(json_encode($warehouse->run('receipts',[])),'unit_cost'),'recepciones de depósito no contienen costos');
test(count($r->run('trace',['lot'=>'L1'])['rows'])===1,'trazabilidad filtra lote sin duplicar destinos');
test($r->run('products',[])['rows'][0]['product']==='Producto original','productos facturados conservan descripción emitida');
foreach(['admin','supervisor','contador','deposito','compras','caja'] as $role){$service=new Reports($db,['id'=>1,'role'=>$role],'2026-11-14');foreach($service->catalog() as $def){$result=$service->run($def['id'],[]);test(isset($result['columns'],$result['summary']),"catálogo ejecutable $role / {$def['id']}");}}
$copy=$db->prepare("INSERT INTO sales(operation_key,payload_hash,customer_id,user_id,number,fiscal_key,issued_on,condition_name,credit_days,due_on,total,balance,snapshot,created_at) VALUES(?,'hash',2,1,?,?,'2026-11-14','credit',30,'2026-11-13',22000,22000,?,'2026-11-14T03:00:00+00:00')");
for($i=2;$i<=51;$i++)$copy->execute(['test'.$i,'FAC'.$i,'test/'.$i,json_encode($snapshot)]);
$first=$r->run('sales',[]);$last=$r->run('sales',['page'=>2]);$all=$r->run('sales',[],false);
test(count($first['rows'])===50&&count($last['rows'])===1&&count($all['rows'])===51,'paginación de pantalla y exportación completa');
test($last['summary'][1]['value']==='1122000','total calculado sobre todas las páginas');
$all['rows'][0]['customer']='=HYPERLINK("prueba")';$stream=fopen('php://temp','w+');ReportOutput::csv($all,$stream);rewind($stream);$csv=stream_get_contents($stream);fclose($stream);
test(str_starts_with($csv,"\xEF\xBB\xBF")&&str_contains($csv,"'=HYPERLINK")&&str_contains($csv,'FAC51'),'exportación UTF-8 completa neutraliza fórmulas');
test(ReportOutput::display('12345678901234567','money')==='Gs. 12.345.678.901.234.567','impresión no pierde precisión de importes grandes');
test($r->run('sales',['customer_id'=>2])['filter_labels']['Cliente']==='Cliente actual','exportaciones identifican filtros con nombres legibles');
$stockTotals=array_column($r->run('inventory',[])['summary'],'value','key');
test(($stockTotals['physical']??'')==='16'&&($stockTotals['reserved']??'')==='2'&&($stockTotals['available']??'')==='11','totales de unidades mantienen físico, reservado y disponible separados');
$expiryUpdate=$db->prepare('UPDATE lots SET expiry=? WHERE id=4');
$expiryUpdate->execute([(new DateTimeImmutable('2026-11-14'))->modify('+90 days')->format('Y-m-d')]);
test(array_column($r->run('expiries',[])['rows'],'band','lot')['L60']==='61–90 días','vencimiento a 90 días incluido en su intervalo');
$expiryUpdate->execute([(new DateTimeImmutable('2026-11-14'))->modify('+91 days')->format('Y-m-d')]);
test(array_column($r->run('expiries',[])['rows'],'band','lot')['L60']==='Más de 90 días','vencimientos mayores a 90 días separados');
echo "Informes verificados.\n";
